def project_files() -> dict[str, bytes]:
    archive = base64.b64decode(_ARCHIVE_B64, validate=True)
    if hashlib.sha256(archive).hexdigest() != _ARCHIVE_SHA256:
        raise ValueError("O conteúdo do script está corrompido; obtenha outra cópia.")
    files: dict[str, bytes] = {}
    with zipfile.ZipFile(io.BytesIO(archive)) as bundle:
        for entry in bundle.infolist():
            name = entry.filename
            parts = PurePosixPath(name).parts
            if (
                not parts
                or PurePosixPath(name).is_absolute()
                or any(part in {".", ".."} for part in parts)
                or "\\" in name
                or ":" in name
                or name in files
                or entry.is_dir()
            ):
                raise ValueError("O pacote contém um caminho inválido.")
            files[name] = bundle.read(entry)
    if not files:
        raise ValueError("O pacote está vazio.")
    return files


def checked_path(root: Path, name: str) -> Path:
    target = root.joinpath(*PurePosixPath(name).parts)
    for parent in (target, *target.parents):
        if parent == root:
            break
        if parent.is_symlink() or not parent.resolve().is_relative_to(root):
            raise ValueError(f"Caminho redirecionado não permitido: {name}")
        if parent != target and parent.exists() and not parent.is_dir():
            raise ValueError(f"Uma pasta necessária é ocupada por um arquivo: {name}")
    return target


def create_project(root: Path, files: dict[str, bytes]) -> tuple[int, int]:
    existing = 0
    for name, content in files.items():
        target = checked_path(root, name)
        if target.exists():
            if not target.is_file() or target.read_bytes() != content:
                raise ValueError(f"Arquivo existente diferente; nenhum arquivo criado: {name}")
            existing += 1
    created = 0
    for name, content in files.items():
        target = checked_path(root, name)
        target.parent.mkdir(parents=True, exist_ok=True)
        try:
            stream = target.open("xb")
        except FileExistsError:
            if target.is_file() and target.read_bytes() == content:
                continue
            raise ValueError(
                f"Arquivo criado por outro processo; operação interrompida: {name}"
            ) from None
        with stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        created += 1
    return created, existing


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--listar", action="store_true", help="Listar arquivos sem criar o projeto")
    args = parser.parse_args()
    # The recipient may invoke this standalone script with an older interpreter.
    if sys.version_info < (3, 11):  # noqa: UP036
        sys.stderr.write("Use Python 3.11 ou superior.\n")
        return 2
    try:
        files = project_files()
        files["criar_projeto.py"] = Path(__file__).read_bytes()
        if args.listar:
            sys.stdout.write("\n".join(files) + "\n")
            return 0
        root = Path.cwd().resolve()
        created, existing = create_project(root, files)
    except (OSError, ValueError, zipfile.BadZipFile) as error:
        sys.stderr.write(f"Não foi possível criar o projeto: {error}\n")
        return 2
    sys.stdout.write(
        f"Projeto criado em: {root}\n"
        f"Arquivos criados: {created}; arquivos idênticos preservados: {existing}.\n"
        "Leia README.md para instalar as dependências e configurar o escopo.\n"
        "Nenhuma dependência foi instalada e nenhuma chamada AWS foi realizada.\n"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
